import Link from "next/link";
import { VendorPageHeader } from "@/components/vendor/page-header";
import { Panel } from "@/components/admin/panel";
export default function Page() { return <div><VendorPageHeader title="Vendor help centre" description="Quick guides to running your business on NaijaSpa." actions={<Link href="/vendor/support" className="text-goldink">Contact support →</Link>}/><Panel>{[['How do I appear on Explore?', 'Your application must be approved, your listing public, and at least one service active. Add a therapist and working hours so customers can book.', '/vendor/profile', 'Business profile'], ['How do I manage appointments?', 'Open a booking to see its payment and status. Confirm paid requests, start confirmed appointments, and mark visits completed through the booking workflow.', '/vendor/bookings', 'Bookings'], ['How do I block time?', 'Use Availability to set your business hours and block a therapist for a closure, holiday or appointment.', '/vendor/availability', 'Availability'], ['How do I receive payouts?', 'Add your Nigerian bank account. Earnings and payout status appear in the ledger after the visit confirmation workflow.', '/vendor/earnings', 'Earnings & payouts'], ['How do I show public contact details?', 'An eligible active paid listing plan unlocks direct public contact. Save your phone and WhatsApp in Listing details.', '/vendor/listing', 'Listing details'], ['How do I add photos?', 'Open Business profile and select photos directly from your device. Images and video allowances follow your current plan.', '/vendor/profile#business-photos', 'Business photos']].map(([question, answer, href, label]) => <details key={question} className="border-b border-line py-4 last:border-0"><summary className="cursor-pointer font-semibold">{question}</summary><p className="mt-3 text-sm text-ink2">{answer}</p><Link href={href} className="mt-2 inline-block text-sm text-goldink">{label} →</Link></details>)}</Panel></div>; }
